    /**
     * 选择酒杯
     */
    showBBSelect(cb) {
        SlotsFacade.soundMgr.playEffect("choose_popup5");
        // this.showBg(true);
        let panel = this.node.getChildByName("panel_beer_bonus_2");
        panel.active = true;
        panel.scale = 0;
        cc.tween(panel)
            .to(0.5, {scale:0.85}, {easing:"backOut"})
            .start();
        let handler = (evt)=>{
            SlotsFacade.soundMgr.playEffect("bs_choose");
            for(let i=1; i<=3; i++) {
                let item = panel.getChildByName("select" + i);
                item.off(cc.Node.EventType.TOUCH_END);
                if(item.id == evt.target.id) {
                    let selectedSpine = panel.getChildByName("spine_choose_effect").getComponent(sp.Skeleton);
                    selectedSpine.node.active = true;
                    selectedSpine.node.x = evt.target.x;
                    selectedSpine.node.y = evt.target.y;
                    selectedSpine.setAnimation(0, "animation", true);
                }else{
                    item.color = new cc.Color().fromHEX("#4C4C4C");
                }
            }
            cc.tween(panel)
                .delay(2)
                .call(()=>{
                    SlotsFacade.soundMgr.playEffect("popup_out");
                })
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    // this.showBg(false);
                    panel.active = false;
                    panel.getChildByName("spine_choose_effect").active = false;
                    if(cb) {
                        cb(evt.target.id);
                    }
                })
                .start();
        };
        for(let i=1; i<=3; i++) {
            let item = panel.getChildByName("select" + i);
            item.id = i;
            item.on(cc.Node.EventType.TOUCH_END, handler);
            item.color = new cc.Color().fromHEX("#FFFFFF");
        }
    },

    /**
     * 显示剩余轮数
     */
    async showBBRound(value) {
        SlotsFacade.soundMgr.playEffect("else_popup");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_beer_bonus_3");
        panel.active = true;
        panel.scale = 0;
        let round = panel.getChildByName("round");
        let final_round = panel.getChildByName("final_round");
        if(value < 5) {
            round.active = true;
            final_round.active = false;
            let label1 = round.getChildByName("round_numb_1").getComponent("ImgSwitchCmp");
            let label2 = round.getChildByName("round_numb_2").getComponent("ImgSwitchCmp");
            label1.setIndex(value-1);
            label2.setIndex(value-1);
        }else {
            round.active = false;
            final_round.active = true;
        }
        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale:0.85}, {easing:"backOut"})
                .delay(1)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    this.showBg(false);
                    panel.active = false;
                    SlotsFacade.soundMgr.playEffect("else_end");
                    res();
                }).start();
        });
    },

    ///////////////////////jp game相关//////////////////////////////
    /**
     * 显示赢取金币
     * @param {number} goldNumb 
     * @param {number} jpType 0~3 mini~grand
     */
    async showWinJpGold(goldNumb, jpType) {
        if(!jpType) {
            jpType = 0;
        }
        SlotsFacade.soundMgr.playEffect("jp_popup1");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_jp_coin");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label").getComponent("LabelRollCmp").startRoll(0, goldNumb);

        let jp_icon = panel.getChildByName("jp_icon").getComponent("ImgSwitchCmp");
        jp_icon.setIndex(jpType);
        cc.tween(panel.getChildByName("jp_icon")).repeatForever(
            cc.tween().to(0.5, {scale:1.2}).to(0.5, {scale:1})
        ).start();
        let okBtn = panel.getChildByName("btn_ok");
        await new Promise(res=>{
            cc.tween(panel)
                .to(0.5, {scale:0.85}, {easing:"backOut"})
                .start();
            let handler = ()=>{
                okBtn.off(cc.Node.EventType.TOUCH_END);
                SlotsFacade.soundMgr.playEffect("popup_out");
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            cc.vv.gameData.checkAutoPlay(okBtn, handler);
            okBtn.on(cc.Node.EventType.TOUCH_END, ()=>{
                okBtn.stopAllActions();
                handler();
            });
        });
    },

