    async showJpGameGuideTips() {
        this.showBg(true);
        let panel = this.node.getChildByName("panel_jpgame_guide_tips");
        panel.opacity = 0xff;
        panel.active = true;
        let spine = panel.getChildByName("pick_huxi").getComponent(sp.Skeleton);
        spine.setAnimation(0, "animation", true);
        // 自动结束
        let p1 = new Promise(res=>{
            cc.tween(panel)
                .delay(3)
                .call(()=>{
                    SlotsFacade.soundMgr.playEffect("popup_out");
                })
                .to(1, {opacity:0})
                .call(()=>{
                    this.showBg(false);
                    panel.active = false;
                    res();
                }).start();
        });
        
        // 手动结束
        let p2 =new Promise(res=>{
            let bg = panel.getChildByName("bg");
            let handler = ()=>{
                bg.off(cc.Node.EventType.TOUCH_END, handler, this);
                this.showBg(false);
                panel.stopAllActions();
                panel.active = false;
                SlotsFacade.soundMgr.playEffect("popup_out");
                res();
            };
            bg.on(cc.Node.EventType.TOUCH_END, handler, this);
        });
        await Promise.race([p1, p2]);
    },
