cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        bgSpine:sp.Skeleton, //背景spine动画
    },

    /**
     * @override
     * @param {*} idx 
     * @param {*} nCount 
     */
    Init:function(idx,nCount, node){
        this._super(idx,nCount, node);
        this.bgSpine = cc.find("reels_bg/reel_bg"+(this._reelIdx+1) + "/spine",this.node.parent.parent).getComponent(sp.Skeleton);
        this.bgSpine.node.active = false;
    },

    getSymbols() {
        return this._symbols;
    },

    /**
     * @override
     */
    playReelStop(){
        this._super();
        for(let i = 0; i < this._symbols.length; i++){
            let item = this._symbols[i]
            for (let info of this._reelState) {
                let id = item.GetShowId();
                if(!SlotsFacade.dm.getGameCfg().isScatter(id)) {
                    continue;
                }
                if (info.isStop) {
                    this.playReelBg(true);
                    return;
                }
            } 
        }
    },

    playReelBg(boo) {
        this.bgSpine.node.active = boo;
    },

    reelMove(dir, num){
        let height = this._cfg.symbolSize.height
        cc.tween(this._holderNode)
            .to(num*0.2,{position:cc.v2(this._holderNode.x,this._holderNode.y + dir * num * height)})
            .start();
    },

    reelReset(dir, num) {
        let height = this._cfg.symbolSize.height;
        this._holderNode.y -= dir * num * height;
    },
})
