/**
 * jpitemType{
 * 1 grand
 * 2 major
 * 3 minor
 * 4 mini
 * 5 x5
 * 6 x3
 * 7 x2
 * }
 */

cc.Class({
    extends: cc.Component,

    properties: {
        panel: cc.Node,
        jp_grand: cc.Node,
        jp_major: cc.Node,
        jp_minor: cc.Node,
        jp_mini: cc.Node,
        icon_diamond: cc.Node,
        particle: cc.Node,

        _bagList: [],
        _rateList: [],
        _data: null,
        _callBack: null,
    },

    onLoad() {
        for (let i = 1; i <= 23; i++) {
            let itemCmp = this.panel.getChildByName("jp_bag" + i).getComponent("TavernWitch_JPBag");
            itemCmp.id = i;
            itemCmp.node.on(cc.Node.EventType.TOUCH_END, this._onTouchBagHandler.bind(this), this);
            this._bagList.push(itemCmp);
        }
        this._reset();
    },

    _reset() {
        this._data = {
            canTouch: false, //是否可点击
            jpCnt: [0, 0, 0, 0], // grand major minor mini 收集到的星星数,
            canRandomAni: true, // 是否可以随机播放钱袋动画
        };
        for (let i = 0; i < this._bagList.length; i++) {
            this._bagList[i].reset();
        }

        this._rateList = [];
    },

    async _onTouchBagHandler(evt) {
        if (!this._data.canTouch) {
            return;
        }
        let bag = evt.target.getComponent("TavernWitch_JPBag");
        let ci = SlotsFacade && SlotsFacade.dm && SlotsFacade.dm.jackpotGame && SlotsFacade.dm.jackpotGame.choiceIdxs
        if (!Array.isArray(ci)) { ci = [] } // By JerryWong
        if (/*SlotsFacade.dm.jackpotGame.choiceIdxs*/ci.includes(bag.id)) {
            return;
        }
        this._data.canTouch = false;
        // 请求消息
        let msg = await SlotsFacade.dm.reqSubGame({ rtype: 3, choiceId: bag.id });
        SlotsFacade.dm.jackpotGame = msg.data.jackpotGame;
        this._initData();
        // let jpNodes = [this.jp_mini, this.jp_minor, this.jp_major, this.jp_grand];
        // for(let i=0; i<jpNodes.length; i++) {
        //     let cnt = msg.data.jackpotGame.jackpotValues[i];
        //     let jpItem = jpNodes[i];
        //     // 显示jp值
        //     jpItem.getChildByName("lbl_num").getComponent(cc.Label).string = Global.FormatNumToComma(cnt);
        // }

        if (msg.data.choiceItem > 4) {
            this._rateList.push(bag);
        }
        await bag.openBag(msg.data.choiceItem);
        await this._moveDiamond(bag, msg.data);
        this._settlement(msg);
    },

    async _settlement(msg) {
        let jpData = msg.data.jackpotGame;
        if (jpData.winCoin > 0) {
            this._data.canRandomAni = false;
            let jpItem = [this.jp_grand, this.jp_major, this.jp_minor, this.jp_mini][msg.data.choiceItem - 1];
            await this._playParticleFly(jpItem);
            let jpNodes = [this.jp_mini, this.jp_minor, this.jp_major, this.jp_grand];
            for (let i = 0; i < jpNodes.length; i++) {
                let cnt = msg.data.jackpotGame.jackpotValues[i];
                let jpItem = jpNodes[i];
                // 显示jp值
                jpItem.getChildByName("lbl_num").getComponent(cc.Label).string = Global.FormatNumToComma(cnt);
            }
            this._showJpWinEffect(msg.data.choiceItem);
            await this._showRestBag(msg.data);
            // 显示jp完成动画
            SlotsFacade.soundMgr.playEffect("jp_stop");
            await SlotsFacade.delayTime(0.5);

            // 显示赢取奖励
            await SlotsFacade.popup.showWinJpGold(jpData.winCoin, 4 - msg.data.choiceItem);
            SlotsFacade.dm.setJackpotWinCoin(jpData.winCoin);
            // 退出
            SlotsFacade.dm.jackpotGame = null;
            this.close();
        } else {
            // 设置可点击
            this._data.canTouch = true;
        }
    },

    async _playParticleFly(jackpotNode) {
        let time = 0;
        for (let i = 0; i < this._rateList.length; i++) {
            let bag = this._rateList[i];
            let par = cc.instantiate(this.particle);
            par.active = true;
            par.parent = this.node.parent;
            let startPos = bag.node.convertToWorldSpaceAR(cc.v2(0, 0));
            startPos = this.node.parent.convertToNodeSpaceAR(startPos);
            let endPos = jackpotNode.convertToWorldSpaceAR(cc.v2(0, 0));
            endPos = this.node.parent.convertToNodeSpaceAR(endPos);
            par.position = startPos;
            time = 0.5;
            cc.tween(par)
                .to(0.5, { position: endPos })
                .start();
        }
        await SlotsFacade.delayTime(time);
    },

    /**
     * 显示剩余钱袋
     */
    async _showRestBag(data) {
        let jpData = data.jackpotGame;
        let choiceItem = data.choiceItem;
        for (let i = 0; i < jpData.choiceIdxs.length; i++) {
            let element = jpData.choiceIdxs[i];
            let bag = this._bagList[element - 1];
            if (bag.itemType == choiceItem || bag.itemType > 4) {
                bag.select(jpData.choiceItems[i]);
            } else {
                bag.unSelect(jpData.choiceItems[i]);
            }
        }
        for (let i = 0; i < jpData.restIdxs.length; i++) {
            let element = jpData.restIdxs[i];
            let bag = this._bagList[element - 1];
            bag.unSelect(jpData.restItems[i]);
        }
        await SlotsFacade.delayTime(2);
    },

    /**
     * 移动钻石
     * @param {*} bag 
     * @param {*} data 
     */
    async _moveDiamond(bag, data) {
        let itemType = data.choiceItem;
        if (itemType > 4) {
            return;
        }
        let startPos = cc.v2(bag.node.x, bag.node.y);
        let diamond_container = [this.jp_grand, this.jp_major, this.jp_minor, this.jp_mini][itemType - 1].getChildByName("diamond_container");
        let diamond = diamond_container.getChildByName("icon" + this._data.jpCnt[itemType - 1]);
        let endPos = this.panel.convertToNodeSpaceAR(diamond.convertToWorldSpaceAR(cc.v2(0, 0)));
        let icon = this.icon_diamond.getChildByName("icon");
        icon.active = true;
        icon.getComponent("ImgSwitchCmp").setIndex(4 - itemType + 1);
        this.icon_diamond.x = startPos.x;
        this.icon_diamond.y = startPos.y;
        await new Promise(res => {
            cc.tween(this.icon_diamond)
                .to(0.5, { x: endPos.x, y: endPos.y })
                .call(() => {
                    icon.active = false;
                    diamond.getComponent("ImgSwitchCmp").setIndex(1);
                    let beishuxuli = this.icon_diamond.getChildByName("beishuxuli").getComponent(sp.Skeleton);
                    beishuxuli.node.active = true;
                    beishuxuli.setAnimation(0, "animation", false);
                    beishuxuli.setCompleteListener(() => {
                        beishuxuli.setCompleteListener(null);
                        beishuxuli.node.active = false;
                    });
                    res();
                })
                .start();
        });
    },

    async close() {
        this._data.canRandomAni = false;
        SlotsFacade.mainPanel.showSceneTransition();
        await SlotsFacade.delayTime(1);
        this.panel.active = false;
        if (SlotsFacade.dm.hasFree()) {
            SlotsFacade.soundMgr.playFreeBgm();
        } else {
            Global.SlotsSoundMgr.stopBgm();
            SlotsFacade.soundMgr.playBgm();
        }

        if (this._callBack) {
            this._callBack();
        }
    },

    _initJp() {
        let jpCnt = this._data.jpCnt;
        let jpNodes = [this.jp_grand, this.jp_major, this.jp_minor, this.jp_mini];
        let jackpotGame = SlotsFacade.dm.getSpinData() ? SlotsFacade.dm.getSpinData().jackpotGame : SlotsFacade.dm.getDeskInfo().jackpotGame;
        for (let i = 0; i < jpNodes.length; i++) {
            let jpType = i + 1;
            let cnt = jpCnt[i];
            let jpItem = jpNodes[i];
            // 显示jp值
            jpItem.getChildByName("lbl_num").getComponent(cc.Label).string = Global.FormatNumToComma(jackpotGame.jackpotValues[jpNodes.length - 1 - i]);
            jpItem.getChildByName("win_effect").active = false;
            // 显示钻石
            let items = jpItem.getChildByName("diamond_container").children;
            for (let j = 0; j < items.length; j++) {
                let icon = items[j].getComponent("ImgSwitchCmp");
                if (j < cnt) {
                    icon.setIndex(1);
                } else {
                    icon.setIndex(0);
                }
            }
        }
    },

    _showJpWinEffect(choiceItem) {
        let jpItem = [this.jp_grand, this.jp_major, this.jp_minor, this.jp_mini][choiceItem - 1];
        jpItem.getChildByName("win_effect").active = true;
    },

    _initBag() {
        let jpData = SlotsFacade.dm.jackpotGame;
        for (let i = 0; i < jpData.choiceIdxs.length; i++) {
            let idx = jpData.choiceIdxs[i];
            let itemType = jpData.choiceItems[i];
            let bag = this._bagList[idx - 1];
            bag.setItemType(itemType);
        }
    },

    /**
     * 随机播放钱袋动画
     */
    async _randomBagSpineAni() {
        if (!this._data.canRandomAni) {
            return;
        }
        let jpData = SlotsFacade.dm.jackpotGame;
        let restIdx = []; // 还未点击的钱袋
        let ci = jpData && jpData.choiceIdxs
        if (!Array.isArray(ci)) { ci = [] }
        for (let i = 1; i <= 23; i++) {
            if (/*jpData.choiceIdxs*/ci.includes(i)) {
                continue;
            }
            restIdx.push(i);
        }

        // 打乱钱袋
        let len = restIdx.length;
        for (let i = 0; i < len; i++) {
            let temp = restIdx[i];
            let idx = Math.floor(Math.random() * len);
            restIdx[i] = restIdx[idx];
            restIdx[idx] = temp;
        }

        // 播放钱袋
        let count = [4, 5, 6][Math.floor(Math.random() * 3)]; // 要播放钱袋的个数
        count = Math.min(len, count);
        for (let i = 0; i < count; i++) {
            let bag = this._bagList[restIdx[i] - 1];
            bag.shake();
        }

        await SlotsFacade.delayTime(2);
        this._randomBagSpineAni();
    },

    _initData() {
        let jpData = SlotsFacade.dm.jackpotGame;
        this._data.jpCnt = [0, 0, 0, 0];
        for (let i = 0; i < jpData.choiceItems.length; i++) {
            let item = jpData.choiceItems[i];
            if (item <= 4) {
                this._data.jpCnt[item - 1]++;
            }
        }
    },

    async _showGuideTips() {
        let jpData = SlotsFacade.dm.jackpotGame;
        if (jpData.choiceIdxs.length == 0) {
            await SlotsFacade.popup.showJpGameGuideTips();
        }
    },

    async open(cb) {
        SlotsFacade.soundMgr.playBgm("jp_bgm");
        this._callBack = cb;
        this.panel.active = true;
        this._reset();
        this._initData();
        this._initJp();
        this._initBag();
        this._randomBagSpineAni();
        await this._showGuideTips();
        this._data.canTouch = true;
    },
});
