cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        
    },

    StartMove:function(){
        this._super();
    },

    //显示symbole
    //id:物品id
    //data:额外传递的数据
    ShowById:function(id,data){
        this._super(id, data);

        let wildGame = SlotsFacade.dm.wildGame;
        if (wildGame && cc.vv.gameData.getGameCfg().isWild(id)) {
            let index = [1, 2, 3, 5, 10, 25].indexOf(wildGame.currMult);
            if (cc.find("multiple", this._showNode)) {
                cc.find("multiple", this._showNode).getComponent("ImgSwitchCmp").setIndex(index);
            }
        }
    },

    //触发动画
    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation(){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,true)
                }
            }
        }
        return isPlay
    },

    playWinTweenAction() {
        if (cc.vv.gameData.getGameCfg().isWild(this._id)) {
            this._showNode.active = false;
            return;
        }
        this._showNode.cleanup();
        cc.tween(this._showNode).repeatForever(
            cc.tween()
                .delay(0.5)
                .to(0.1, {opacity:0})
                .delay(0.3)
                .to(0.1, {opacity:0xff})
                .delay(1)
        ).start();
    },

    stopWinTweenAction(){
        if (cc.vv.gameData.getGameCfg().isWild(this._id)) {
            this._showNode.active = true;
            return;
        }
        this._showNode.cleanup()
        this._showNode.opacity = 0xff;
    },

    setVisible(isVisible) {
        if (this._showNode) {
            this._showNode.active = isVisible;
        }
    },
});
