cc.Class({
    extends: cc.Component,

    properties: {
        roundCount: 10,    // 圈数
        _canSpin:false,      // 是否可转
        _data:null,
        _callBack:null,      // 完成后回调

        panel:cc.Node,
        bg: cc.Node,
        board:cc.Node,
        btn_spin:cc.Node,
        spine_spin:sp.Skeleton,
        spine_win:sp.Skeleton,
    },

    _getRotation(index) {
        let ret = -this.roundCount * 360;
        let unitAngle = 360/6;
        let indexsAngle = [
            0,
            -360+unitAngle*1,
            -360+unitAngle*2,
            -360+unitAngle*3,
            -360+unitAngle*4,
            -360+unitAngle*5
        ];
        ret += indexsAngle[index];
        return ret;
    },

    onLoad() {
        this._initListener();
    },

    _initListener() {
        this.btn_spin.on(cc.Node.EventType.TOUCH_END, this._onStartWheelHandler.bind(this), this);
    },

    async _onStartWheelHandler() {
        if(!this._canSpin) {
            return;
        }
        this.btn_spin.stopAllActions();
        SlotsFacade.soundMgr.playEffect("wheel_click");
        this._canSpin = false;
        let msg = await SlotsFacade.dm.reqSubGame({rtype:1});
        this._data = msg.data;
        this.spine_spin.setAnimation(0, "animation2", false);
        this.spine_spin.setCompleteListener(()=>{
            this.spine_spin.setCompleteListener(null);
            this.spine_spin.setAnimation(0, "animation3", true);
        });
        this._startWheel();
    },

    _reset() {
        this.board.angle = 0;
        this.bg.active = false;
        this.spine_win.node.active = false;
    },

    async _startWheel() {
        SlotsFacade.soundMgr.playEffect("wheel_spin");
        await new Promise((res)=> {
            cc.tween(this.board)
                .to(8, {angle:this._getRotation(this._data.id-1)}, { easing: 'quartInOut' })
                .call(()=> {
                    this.spine_win.node.active = true;
                    SlotsFacade.soundMgr.playEffect("wheel_still");
                    res();
                })
                .start();
        });
        await SlotsFacade.delayTime(2);
        this._completeWheel();
    },

    /**
     * 旋转完毕
     * @param data
     * @returns {Promise<void>}
     * @private
     */
    async _completeWheel() {
        if(this._data.coin) {
            SlotsFacade.soundMgr.playEffect("wheel_popup3");
            await SlotsFacade.popup.showCollectGold(this._data.coin);
            SlotsFacade.dm.addCoin(this._data.coin);
        }
        await this.close();
        if(this._callBack) {
            this._callBack(this._data);
        }
    },

    _freshView() {
        let wheelItems = SlotsFacade.dm.energyData.progressData.wheelItems;
        for(let i=0; i<wheelItems.length; i++) {
            let itemData = wheelItems[i];
            let label = this.board.getChildByName("label" + (i+1)).getComponent(cc.Label);
            label.string = Global.convertNumToShort(itemData.coin);
        }
    },

    /**
     * 开始 开始转盘流程
     */
    async open(cb) {
        SlotsFacade.bottomCmp.ShowBtnsByState("unstoped");
        SlotsFacade.soundMgr.playEffect("wheel_in");
        this._callBack = cb;
        this._reset();
        this._canSpin = true;
        this._freshView();

        this.bg.active = true;
        this.bg.opacity = 128;
        
        this.spine_spin.node.active = true;
        this.spine_spin.setAnimation(0, "animation1", true);

        this.panel.active = true;
        this.panel.scale = 0;
        cc.tween(this.panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start();

        await cc.vv.gameData.awaitTime(0.5);

        cc.vv.gameData.checkAutoPlay(this.btn_spin, async ()=>{
            if(!this._canSpin) {
                return;
            }
            SlotsFacade.soundMgr.playEffect("wheel_click");
            this._canSpin = false;
            let msg = await SlotsFacade.dm.reqSubGame({rtype:1});
            this._data = msg.data;
            this.spine_spin.setAnimation(0, "animation2", false);
            this.spine_spin.setCompleteListener(()=>{
                this.spine_spin.setCompleteListener(null);
                this.spine_spin.setAnimation(0, "animation3", true);
            });
            this._startWheel();
        });
    },

    async close() {
        return new Promise((res) => {
            // 隐藏背景
            cc.tween(this.bg)
                .to(0.5, {opacity:0})
                .call(()=>{
                    this.bg.active = false;
                })
                .start();

            // 隐藏转盘
            cc.tween(this.panel)
                .to(0.5, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    this.panel.active = false;
                    res();
                })
                .start();
        });
    },
});
