/**
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
       wildNode:cc.Node,
    },

    onLoad() {
        this._super();
        this.wildNode = this.node.getChildByName("wild_node");
    },

    //重写
    StartMove:function(){
        this._super();
        this.resetReelBg();
        this.wildNode.active = false;
        // for (let i = 0; i < cc.vv.gameData.getGameCfg().row; i++) {
        //     let symbol = this._reels[2].GetSymbolByRow(i);
        //     if (symbol) {
        //         symbol.setVisible(true);
        //     }
        //
        // }
        for (let symbol of this._reels[2].getSymbols()) {
            if (symbol) {
                symbol.setVisible(true);
            }
        }
        if(SlotsFacade.dm.GetTotalFree() == 0) {
            SlotsFacade.soundMgr.playBgm();
        }
    },

    //设置reel旋转的状态；
    //是否加速框；
    //是否加速旋转
    //是否停止音效；
    //是否播放背景特效
    SetReelStateInfo:function(cards){
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let id = cards[i]
            let col = i % this._col
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);
            let haveCount = 0
            let isContinuous = true
            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount-1 && stateInfo.counts[i] > 0 && isContinuous) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                haveCount += reelCountOfID > 1 ? 1 : reelCountOfID;
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount && isContinuous) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                }
                if (stateInfo.continuous && stateInfo.counts[i] > 0 && reelCountOfID == 0) {
                    isContinuous = false
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    //重写：小游戏取的数据不一样
    onMsgSpine:function(msg){
        SlotsFacade.flowCtrl.onSpinMsg(msg);
    },

    //重写：显示bonus中奖
    OnSpinEnd:function(){
        SlotsFacade.flowCtrl.spinEnd();
    },

    //重写  重连进入房间
    ReconnectShow:function(){
        this.scheduleOnce(()=>{
            SlotsFacade.flowCtrl.enterRoom();
        });
    },

    /**
     * 播放scatter 中奖动画
     */
    async playScatter(indexs) {
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 播放bonus 中jp动画
     */
    async playBonus(indexs) {
        if(!indexs || indexs.length < 1) {
            return;
        }
        SlotsFacade.soundMgr.playEffect("trigger_jp");
        SlotsFacade.soundMgr.playEffect("bell");
        indexs.forEach(element => {
            let item = this.GetSymbolByIdx(element);
            item.playTriggerAnimation();
        });
        await SlotsFacade.delayTime(1.5);
    },

    /**
     * 批量获取symbol
     */
    getSymbolsByServerIds(ids) {
        let ret = [];
        ids.forEach(element => {
            ret.push(this.GetSymbolByIdx(element));
        });
        return ret;
    },
    
    showAllSymbolsToNormal() {
        this._reels.forEach(element => {
            element._symbols.forEach(s => {
                s.ShowKuang(false);
                s.ShowNormal();
            });
        });
    },

    /**
     * 通过服务器idx获取全局坐标
     * @param {*} idx 
     */
    getIdxGlobalPos(idx) {
        let col = (idx - 1) % this._col;
        let row = this._row - Math.floor((idx -1)/this._col) -1
        let reel = this._reels[col];
        let pos = reel.GetSymbolPosByRow(row);
        return reel.node.getChildByName("mask").convertToWorldSpaceAR(pos);
    },

    /**
     * 重置reel背景
     */
    resetReelBg() {
        this._reels.forEach(element => {
            element.playReelBg(false);
        });
    },

    /**
     * 播放wild动画
     * @param {*} multiple 
     */
    async playWild(multiple) {
        let cards = SlotsFacade.dm.afterProcessingCards;
        cc.log(cards);
        let cfg = cc.vv.gameData.getGameCfg();
        if (cfg.isWild(cards[2]) && cfg.isWild(cards[22])) {
            // 整列wild且不需要移动
        } else if (cfg.isWild(cards[2]) && !cfg.isWild(cards[22])) {
            // 下面不是wild,那么要往上填wild图标
            let firstRow = 4;
            for (let i = 4; i >= 0; i--) {
                if (cfg.isWild(cards[i * 5 + 2])) {
                    firstRow = i;
                    break;
                }
            }
            let array = [];
            for (let i = 0; i < 4 - firstRow ; i++) {
                array.push(103 - firstRow - i <= 100 ? 1 : 103 - firstRow - i);
            }
            this._reels[2].AppendSymbol(array, 2);
            this._reels[2].reelMove(-1, array.length);
            SlotsFacade.soundMgr.playEffect("wild_movement");
            cc.log(array);

            await SlotsFacade.delayTime(0.2 * array.length);
            this._reels[2].reelReset(-1, array.length);
            this._reels[2].DelAppendSymbol();

        } else if (!cfg.isWild(cards[2]) && cfg.isWild(cards[22])) {
            // 上面不是wild，那么要往下开始填
            let firstRow = 0;
            for (let i = 0; i < 5; i++) {
                if (cfg.isWild(cards[i * 5 + 2])) {
                    firstRow = i;
                    break;
                }
            }
            let array = [];
            for (let i = 0; i < firstRow; i++) {
                array.push(104 - (firstRow - i - 1));
            }
            cc.log(array);
            this._reels[2].AppendSymbol(array, 1);
            cc.log(this._reels[2].getSymbols());
            this._reels[2].reelMove(1, array.length);
            SlotsFacade.soundMgr.playEffect("wild_movement");
            await SlotsFacade.delayTime(0.2 * array.length);
            this._reels[2].reelReset(1, array.length);
            this._reels[2].DelAppendSymbol();
        }

        this.wildNode.active = true;
        this.wildNode.stopAllActions();

        cc.log(this._reels[2].getSymbols());
        // for (let i = 0; i < cfg.row; i++) {
        //     let symbol = this._reels[2].GetSymbolByRow(i);
        //     if (symbol) {
        //         symbol.setVisible(false);
        //     } else {
        //         console.log("--------------------------------");
        //     }
        // }
        for (let symbol of this._reels[2].getSymbols()) {
            if (symbol) {
                symbol.setVisible(false);
            }
        }
        SlotsFacade.soundMgr.playEffect("wild_shining");
        let icon1 = this.wildNode.getChildByName("multiple1").getComponent("ImgSwitchCmp");
        let icon2 = this.wildNode.getChildByName("multiple2").getComponent("ImgSwitchCmp");
        let index = [1, 2, 3, 5, 10, 25].indexOf(multiple);
        let spine1 = this.wildNode.getChildByName("spine1").getComponent(sp.Skeleton);
        let spine2 = this.wildNode.getChildByName("spine2").getComponent(sp.Skeleton);
        if(index !== -1) {
            icon1.setIndex(index);
            icon2.setIndex(index);
            spine2.node.active = true;
            spine2.setAnimation(0, "animation", false);
            spine2.setCompleteListener(()=>{
                spine2.setCompleteListener(null);
                spine2.node.active = false;

                spine1.setAnimation(0, "animation1", false);
                spine1.setCompleteListener((track)=>{
                    let name = track.animation ? track.animation.name : "";
                    if (name === "animation1") {
                        spine1.clearTracks();
                        spine1.setToSetupPose();
                        spine1.setAnimation(0, "animation2", false);
                    } else if (name === "animation2") {
                        spine1.clearTracks();
                        spine1.setToSetupPose();
                        spine1.setAnimation(0, "animation3", false);
                    } else if (name === "animation3") {
                        spine1.clearTracks();
                        spine1.setToSetupPose();
                        spine1.setAnimation(0, "animation1", false);
                    }
                });
            });
        }else {
            console.log(">>>> #error#playWild#倍数错误", multiple);
        }
    }
});
