/**
 * 游戏流程控制
 * @class TavernWitch_FlowCtrl
 */
cc.Class({
    extends: cc.Component,

    /**
     * 进入房间
     */
    async enterRoom() {
        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            SlotsFacade.bottomCmp.SetWin(nTotal)
            this.enterFreeGame();
        }
        if(SlotsFacade.dm.energyData.state > 0) {
            await new Promise(res=>{
                SlotsFacade.collectGame.open(false, res);
            });
        }
        if(SlotsFacade.dm.jackpotGame) {
            await this.enterJpGame();
        }
        SlotsFacade.slots.CanDoNextRound();
    },

    /**
     * 收到spin消息
     * @param {*} msg 
     */
    async onSpinMsg(msg) {
        SlotsFacade.slots._gameInfo = msg;
        SlotsFacade.slots.SetReelStateInfo(msg.resultCards)
        let cards = SlotsFacade.dm.processResultCards(msg.resultCards);
        SlotsFacade.dm.afterProcessingCards = cards.concat();
        SlotsFacade.slots.SetSlotsResult(cards)
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        if(!SlotsFacade.dm.isFistTriggerFree()) {
            SlotsFacade.slots.resetReelBg();
        }
        // 能量收集
        this.collectEnergy();
        // 改变倍数
        await SlotsFacade.character.changeMultiple();
        // 显示中奖路线
        SlotsFacade.slots.ShowWinTrace();
        // 更新金币
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
        });
        // 进入地图关卡
        await this.enterCollectGame();
        // 进入jpgame
        await this.enterJpGame();
        await SlotsFacade.delayTime(0.3);
        if(SlotsFacade.dm.isTriggerFree()) {
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            await SlotsFacade.slots.playScatter(SlotsFacade.dm.getScatterIndexs());
            await SlotsFacade.popup.showWinFreeCnt(SlotsFacade.dm.triggerFreeCnt(), SlotsFacade.dm.isFistTriggerFree());
            if(SlotsFacade.dm.isFistTriggerFree()) {
                SlotsFacade.slots.Backup();
                SlotsFacade.mainPanel.showSceneTransition();
                await SlotsFacade.delayTime(1);
                this.enterFreeGame();
            }
            SlotsFacade.slots.CanDoNextRound()
        }else if(cc.vv.gameData.hasFree()) {
            SlotsFacade.slots.CanDoNextRound();
        }else if(cc.vv.gameData.isLastEndFree()) {
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            await SlotsFacade.popup.showWinFreeGold(SlotsFacade.dm.getFreeWinCoin());
            SlotsFacade.mainPanel.showSceneTransition();
            await SlotsFacade.delayTime(1);
            SlotsFacade.slots.Resume();
            SlotsFacade.character.changeMultipleExitFree();
            Global.SlotsSoundMgr.stopBgm();
            this.enterNormalGame();
            // 更新金币
            await SlotsFacade.delayTime(0.5);
            let nWin = cc.vv.gameData.GetGameTotalFreeWin()
            let nTotal = nWin
            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
            });
            SlotsFacade.slots.CanDoNextRound()
        }else {
            SlotsFacade.slots.CanDoNextRound()
        }
    },

    /**
     * 收集能量
     */
    async collectEnergy() {
        let energyData = SlotsFacade.dm.energyData.progressData;
        if(energyData && energyData.currCnt) {
            let items = SlotsFacade.slots.getSymbolsByServerIds(SlotsFacade.dm.getCollectSymbolIndexs());
            let posArr = [];
            items.forEach(v => {
                posArr.push(v.node.convertToWorldSpaceAR(cc.v2(0, 0)));
            });
            await SlotsFacade.collectProgress.collectEnergy(posArr, SlotsFacade.dm.getCollectPercent());
        }
    },

    /**
     * 进入免费游戏
     */
    enterFreeGame() {
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.mainPanel.showBg(true);
        SlotsFacade.soundMgr.playFreeBgm();
        SlotsFacade.character.changeMultipleTriggerFree();
    },

    /**
     * 进入普通游戏
     */
    enterNormalGame() {
        SlotsFacade.bottomCmp.ShowFreeModel(false);
        SlotsFacade.mainPanel.showBg(false);
        SlotsFacade.soundMgr.playBgm();
    },

    /**
     * 进入地图游戏
     */
    async enterCollectGame() {
        let energyData = SlotsFacade.dm.energyData;
        if(energyData.state == 1) {
            await SlotsFacade.collectProgress.showEnterCollectGameAni();
            await new Promise(res=>{
                SlotsFacade.collectProgress.setProgress(0);
                SlotsFacade.collectGame.open(false, res);
            });
        }
    },

    /**
     * 进入jp游戏
     */
    async enterJpGame() {
        let jackpotGame = SlotsFacade.dm.jackpotGame;
        if(!jackpotGame) {
            return;
        }
        await SlotsFacade.slots.playBonus(SlotsFacade.dm.getBonusIndexs());
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        await SlotsFacade.popup.showJpFeatureTips();
        SlotsFacade.mainPanel.showSceneTransition();
        await SlotsFacade.delayTime(1);
        await new Promise(res=>{
            SlotsFacade.jpGame.open(res);
        });

        await new Promise((success)=>{
            let winCoin = SlotsFacade.dm.getJPGameWinCoin();
            let totalWin = winCoin;
            if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() !== cc.vv.gameData.GetFreeTime()) {
                totalWin = SlotsFacade.dm.getSpinData() ? cc.vv.gameData.GetGameTotalFreeWin() + winCoin : cc.vv.gameData.GetTotalFreeWin() + winCoin;
            }
            cc.vv.gameData.AddCoin(winCoin);
            SlotsFacade.slots.ShowBottomWin(winCoin, totalWin, true, ()=>{
                success();
            });
        });
    },
})