
/**
 * 收集进度
 * @class TavernWitch_CollectProgress
 */
cc.Class({
    extends: cc.Component,

    properties: {
        icon_energy:cc.Node,        // 能量收集图标
        spine_end:sp.Skeleton,      // 进度条尾部spine动画
        btn_enter: cc.Node,         // 进入收集游戏按钮节点
        progressBar: cc.Node,       // 进度条节点
        spine_full: sp.Skeleton,    // 集满能量条，能量条上的动画
        collect_track_particle:cc.Node, // 能量收集轨道粒子动画

        _isOpen:false,   // 是否打开收集
    },

    onLoad() {
        this._initListener();
        this._init();
    },

    _initListener() {
        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);
        this.btn_enter.on(cc.Node.EventType.TOUCH_END, this._onEnterHandler.bind(this), this);
        this.progressBar.on(cc.Node.EventType.TOUCH_END, ()=>{
            if(!this._isOpen) {
                this._openCollect();
            }
        }, this);
    },

    _init() {
        this.setProgress(SlotsFacade.dm.getCollectPercent());
        this.showCollect(true);
    },

    _onEnterHandler() {
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.collectGame.open(true, ()=>{
            SlotsFacade.bottomCmp.ShowBtnsByState("idle");
        });
    },

    /**
     * 打开收集
     */
    _openCollect() {
        // 如果已经打开收集 返回
        if(this._isOpen) {
            return;
        }
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.getDeskInfo().needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        cc.vv.gameData._serverRawMult = needBet;
        cc.vv.UserManager.setEnterSelectBet(null);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 收集能量
     * @param {Array<cc.Vec2>} globalPosArr
     * @param percent
     */
    async collectEnergy(globalPosArr, percent) {
        let endPos = this.icon_energy.getPosition();
        let promiseArr = [];
        globalPosArr.forEach(v=>{
            let pos = this.node.convertToNodeSpaceAR(v);
            let lz = cc.instantiate(this.collect_track_particle);
            lz.parent = this.node;
            lz.x = pos.x;
            lz.y = pos.y;
            lz.active = true;
            let p = lz.getComponent(cc.ParticleSystem);
            p.resetSystem();

            promiseArr.push(new Promise((res)=>{
                cc.tween(lz)
                    .then(cc.bezierTo(
                        0.6,
                        [
                            cc.v2(lz.x+(endPos.x-lz.x)*0.11, lz.y+(endPos.y-lz.y)*-0.19),
                            cc.v2(lz.x+(endPos.x-lz.x)*0.2, lz.y+(endPos.y-lz.y)*-0.19),
                            cc.v2(endPos.x, endPos.y),
                        ]
                    ))
                    .then(cc.tween().call(
                        ()=> {
                            lz.removeFromParent();
                            res();
                        }
                    ))
                    .start();
            }));
        });
        SlotsFacade.soundMgr.playEffect("symbol_fly");
        await Promise.all(promiseArr);
        this._playHeadSpine();
        this.setProgress(percent, true);
    },

    _playHeadSpine() {
        let spine = this.icon_energy.getChildByName("spine").getComponent(sp.Skeleton);
        spine.node.active = true;
        spine.setAnimation(0, "animation", false);
        spine.setCompleteListener(()=>{
            spine.setCompleteListener(null);
            spine.node.active = false;
        });
    },

    /**
     * 显示收集界面
     * @param isInit
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            if(!this._isOpen) {
                if(isInit) {
                    this.spine_full.node.active = false;
                }else {
                    this.spine_full.node.active = true;
                    SlotsFacade.soundMgr.playEffect("lock");
                    this.spine_full.setAnimation(0, "animation2", false);
                }
            }
        }else {
            this.spine_full.node.active = true;
            if(isInit) {
                this.spine_full.setAnimation(0, "animation4", false);
            }else {
                if(this._isOpen) {
                    SlotsFacade.soundMgr.playEffect("lock");
                    this.spine_full.setAnimation(0, "animation3", false);
                }
            }
        }
        this._isOpen = boo;
    },

    /**
     * 设置进度
     * @param percent
     */
    setProgress(percent, needTransform) {
        let w = this.progressBar.width;
        let toX = -w + percent * w;
        let spine_progress = this.progressBar.getChildByName("spine_progress");
        if(needTransform) {
            let collect_effect = spine_progress.getChildByName("collect_effect").getComponent(sp.Skeleton);
            collect_effect.node.active = true;
            collect_effect.setAnimation(0, "animation", false);
            collect_effect.setCompleteListener(()=>{
                collect_effect.setCompleteListener(null);
                collect_effect.node.active = false;
            });
            cc.tween(spine_progress).to(0.5, {x:toX}).start();
        }else {
            spine_progress.x = toX;
        }
    },

    /**
     * 进入收集游戏动画
     */
    async showEnterCollectGameAni() {
        // 能量挤满进度条
        this.spine_full.node.active = true;
        SlotsFacade.soundMgr.playEffect("bell");
        await new Promise(res=>{
            this.spine_full.setAnimation(0, "animation1", false);
            this.spine_full.setCompleteListener(()=>{
                this.spine_full.setCompleteListener(null);
                //this.spine_full.node.active = false;
                res();
            });
        });
        await new Promise(res=>{
            this.spine_end.setAnimation(0, "animation2", false);
            this.spine_end.setCompleteListener(()=>{
                this.spine_end.setCompleteListener(null);
                this.spine_end.setAnimation(0, "animation1", true);
                res();
            });
        });
    }
});
