/**
 * 角色动画控制
 */
cc.Class({
    extends: cc.Component,

    properties: {
        roleMultiple:sp.Skeleton,   // 大于1倍的角色
        roleMultipleLabel:cc.Node,  // 倍数显示
        normalRole:sp.Skeleton, // 普通角色
        fly_particle:cc.ParticleSystem, // 倍数飞行粒子
        lightList:[cc.Node],    // 灯列表
        mutongList:[cc.Node],   // 木桶列表
        tipsLight:cc.Node,      // 亮灯提示
        _multiple:1,            // 当前倍数
    },

    onLoad() {
        let wildGame = SlotsFacade.dm.wildGame;
        if(wildGame.currMult > 1) {
            this.roleMultiple.node.active = true;
            this.roleMultiple.setAnimation(0, "animation2_1", true);
            // this.normalRole.setAnimation(0, "animation4_1", false);
            this.normalRole.node.active = false;
        }else {
            this.roleMultiple.node.active = false;
            this.normalRole.setAnimation(0, "idle", true);
        }
        this.setMultiple(wildGame.currMult);
        this.showLight(wildGame.restCnt)
    },

    setMultiple(multiple) {
        this._multiple = multiple;
        this.roleMultipleLabel.active = multiple > 1;
        let index = SlotsFacade.dm.getMultipleIndex(multiple);
        if(multiple > 1) {
            this.roleMultipleLabel.getComponent("ImgSwitchCmp").setIndex(index - 1);
            SlotsFacade.soundMgr.playEffect([
                "", 
                "multi_up1",
                "multi_up2",
                "multi_up3",
                "multi_up4",
                "multi_up5",
            ][index]);
        }

        let enableColor = new cc.Color().fromHEX("#ffffff");
        let disableColor = new cc.Color().fromHEX("#545454");
        for(let i=0; i<this.mutongList.length; i++) {
            let element = this.mutongList[i];
            let icon = element.getChildByName("icon");
            let spine = element.getChildByName("spine").getComponent(sp.Skeleton);
            let multiple = element.getChildByName("multiple");
            if(index == i) {
                icon.color = enableColor;
                multiple.color = enableColor;
                spine.node.active = true;
                spine.setAnimation(0, "animation2", true);
            }else {
                icon.color = disableColor;
                multiple.color = disableColor;
                spine.node.active = false;
            }
        }
    },

    /**
     * 显示亮灯数
     * @param {number} cnt 
     */
    showLight(cnt) {
        // if(cnt > 0) {
        //
        // }
        this.tipsLight.active = cnt > 0;
        for(let i=0; i<this.lightList.length; i++) {
            let element = this.lightList[i];
            let state = element.getChildByName("state").getComponent("ImgSwitchCmp");
            let spine = element.getChildByName("spine").getComponent(sp.Skeleton);
            if(i < cnt) {
                if (state.getIndex() === 0) {
                    SlotsFacade.soundMgr.playEffect(["light1", "light2", "light3"][i]);
                }
                state.setIndex(1);
                spine.node.active = true;
            }else {
                state.setIndex(0);
                spine.node.active = false;
            }
        }
    },

    /**
     * 切换到多倍数
     */
    async _toMultiple(multiple) {
        SlotsFacade.soundMgr.playEffect("logo_change2");
        this.setMultiple(multiple ? multiple : 2);
        this.normalRole.setAnimation(0, "skill_2", false);
        this.normalRole.setCompleteListener(()=>{
            this.normalRole.setCompleteListener(null);
            this.normalRole.node.active = false;
        })
        await SlotsFacade.delayTime(1);
        this.roleMultiple.node.active = true;
        this.roleMultiple.setAnimation(0, "animation1_1", false);
        this.roleMultiple.setCompleteListener(()=>{
            this.roleMultiple.setCompleteListener(null);
            this.roleMultiple.setAnimation(0, "animation2_1", true);
        });
    },

    /**
     * 切换到1倍
     */
    async _toNormal() {
        SlotsFacade.soundMgr.playEffect("logo_change1");
        this.roleMultiple.setAnimation(0, "animation3_1", false);
        this.roleMultiple.setCompleteListener(()=>{
            this.roleMultiple.setCompleteListener(null);
            this.roleMultiple.node.active = false;
        });
        await SlotsFacade.delayTime(1);
        this.normalRole.node.active = true;
        this.normalRole.setAnimation(0, "skill", false);
        this.normalRole.setCompleteListener(()=>{
            this.normalRole.setCompleteListener(null);
            this.normalRole.setAnimation(0, "idle", true);
            this.setMultiple(1);
        });
    },

    /**
     * 更改倍数
     */
    async changeMultiple() {
        let wildGame = SlotsFacade.dm.wildGame;
        this.showLight(SlotsFacade.dm.getSpinData().wildGame.restCnt);
        if (wildGame.restCnt === 0 && this._multiple !== 1) {
            this._toNormal();
        }
        if(wildGame.currMult === this._multiple && !SlotsFacade.dm.hasWild()) {
            return;
        }
        let diff = wildGame.currMult - this._multiple;
        if(diff > 0) {  // 倍数变大
            await SlotsFacade.slots.playWild(wildGame.currMult);
            await SlotsFacade.delayTime(0.45);
            await this.moveParticle(wildGame.currMult);
            if(this._multiple == 1) { // 切换到酒杯
                this._toMultiple();
            }else { // 改变倍数
                SlotsFacade.soundMgr.playEffect("logo_change1");
                this.setMultiple(wildGame.currMult);
            }
        }else {
            if (SlotsFacade.dm.hasWild()) {
                await SlotsFacade.slots.playWild(wildGame.currMult);
                await SlotsFacade.delayTime(0.45);
                await this.moveParticle(wildGame.currMult);
            } else {
                this._toNormal();
            }
        }
        this._multiple = wildGame.currMult;
    },

    changeMultipleTriggerFree() {
        let wildGame = SlotsFacade.dm.wildGame;
        SlotsFacade.soundMgr.playEffect("logo_change1");
        this._multiple = wildGame.currMult;
        if(this._multiple === 1) {
            this._toNormal();
        }else {
            SlotsFacade.soundMgr.playEffect("logo_change1");
            this._toMultiple(wildGame.currMult);
        }
    },

    changeMultipleExitFree() {
        let mult = cc.vv.gameData.getSpinData().wildGame.currMult;
        SlotsFacade.soundMgr.playEffect("logo_change1");
        this._multiple = mult;
        if(this._multiple === 1) {
            this._toNormal();
        }else {
            SlotsFacade.soundMgr.playEffect("logo_change1");
            this.setMultiple(mult);
        }
    },

    async moveParticle(mult) {
        let index = SlotsFacade.dm.getMultipleIndex(mult);
        let mutongPos = this.mutongList[index].convertToWorldSpaceAR(cc.v2(0,0));
        mutongPos = this.fly_particle.node.parent.convertToNodeSpaceAR(mutongPos)
        let wildPos = SlotsFacade.slots.wildNode.convertToWorldSpaceAR(cc.v2(0,0));
        wildPos = this.fly_particle.node.parent.convertToNodeSpaceAR(wildPos);
        this.fly_particle.node.x = wildPos.x;
        this.fly_particle.node.y = wildPos.y;
        this.fly_particle.resetSystem();
        this.fly_particle.node.active = true;
        await new Promise(res=>{
            cc.tween(this.fly_particle.node)
            .to(0.5, {x:mutongPos.x, y:mutongPos.y})
            .call(()=>{
                this.fly_particle.node.active = false;
                res();
            })
            .start();
        });
    }
});
