/**
 * 规则介绍
 * @class TavernWitch_GameRule
 */
cc.Class({
    extends: cc.Component,

    properties: {
        bg_mask:cc.Node,
        content_node:cc.Node,
        pageView:cc.PageView,
        btnPre:cc.Button,
        btnNext:cc.Button,
        btnExit:cc.Button
    },

    onLoad() {
        this.btnPre.node.on("click", this.btnPreHandler.bind(this), this);
        this.btnNext.node.on("click", this.btnNextHandler.bind(this), this);
        this.btnExit.node.on("click", this.btnExitHandler.bind(this), this);
        this.pageView.node.on("scroll-ended", this.scrollEndHandler.bind(this), this);
    },

    btnPreHandler() {
        let currIndex = this.pageView.getCurrentPageIndex();
        let toIndex = currIndex - 1;
        if(toIndex >= 0) {
            this.pageView.scrollToPage(toIndex, 0.5);
        }
    },

    btnNextHandler() {
        let currIndex = this.pageView.getCurrentPageIndex();
        let toIndex = currIndex + 1;
        if(toIndex < this.pageView.getPages().length) {
            this.pageView.scrollToPage(toIndex, 0.5);
        }
    },

    scrollEndHandler() {
        // let currIndex = this.pageView.getCurrentPageIndex();
        // this.btnPre.node.active = currIndex != 0;
        // this.btnNext.node.active = currIndex < this.pageView.getPages().length-1;
    },

    btnExitHandler() {
        new Promise(res=>{
            cc.tween(this.content_node)
                .to(0.3, {opacity:0, scale:0}, {easing:"backIn"})
                .call(()=>{
                    res();
                })
                .start();
        }).then((data)=>{
            cc.tween(this.bg_mask)
                .to(0.1, {opacity:0})
                .call(()=>{
                    this.bg_mask.opacity = 128;
                    this.bg_mask.active = true;
                    this.content_node.opacity = 0xff;
                    this.content_node.scale = 1;
                    this.content_node.active = true;
                    this.node.active = false;
                })
                .start();
        })
    }
});
