/**
 * @class TavernWitch_GameData
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        energyData  : null,   // 能量数据

        wildGame: null,         // wild 数据

        wildMultipleList:null,  // 倍数倍数列表

        jackpotGame:null,   // jackpotGame 数据

        afterProcessingCards:null, // 处理过后的symbols

        _jackpotWinCoin: 0,
    },

    init(deskInfo,gameId,gameJackpot) {
        this.energyData = deskInfo.bonusGame;
        if (deskInfo.wildGameInFree) {
            this.wildGame = deskInfo.wildGameInFree;
        } else {
            this.wildGame = deskInfo.wildGame;
        }

        this.wildMultipleList = [1, 2, 3, 5, 10, 25];
        this.jackpotGame = deskInfo.jackpotGame;
        this._super(deskInfo,gameId,gameJackpot);
    },


    addCoin(coin) {
        this.setCoins(this.GetCoin() + coin);
    },

    setJackpotWinCoin(coin) {
        this._jackpotWinCoin = coin;
    },

    getJPGameWinCoin() {
        return this._jackpotWinCoin;
    },

    OnRcvNetSpine:function(msg){
        if(msg.code == 200){
            this.energyData = msg.bonusGame
            this.freeTurnTable = msg.freeTurnTable;
            this.freeCnt = msg.freeCnt || 0;
            this.totalFreeCnt = msg.allFreeCnt || 0;

            if (msg.wildGameInFree) {
                this.wildGame = msg.wildGameInFree;
            } else {
                this.wildGame = msg.wildGame;
            }
            this.jackpotGame = msg.jackpotGame;
        }
        this._super(msg);
    },

    getSpinData() {
        return this._gameInfo;
    },

    /**
     * 处理服务器发回的牌，用于替换酒桶id
     */
    processResultCards(cards) {
        let result = cards.concat();
        let row = 5;
        let col = 5;
        let scatterId = 2;
        let scatterIdDown = 2; // 朝下
        let scatterIdUp = 201; // 朝上
        for(let i=0; i<cards.length; i++) {
            let c = cards[i];
            if(c != scatterId) {
                continue;
            }
            let crrRow = Math.floor(i/col); // 当前所处的行 0-4
            let upperIsScatter = false; // 这张牌上面是否有scatter
            let downIsScatter = false;  // 这张牌下面是否有scatter
            if(crrRow == 0) { // 如果在第一行上面必然没有scatter
                upperIsScatter = false;
            }else {
                upperIsScatter = cards[i-col] == scatterId;
            }
            if(crrRow == 4) {
                downIsScatter = false;// 如果在最后一行下面面必然没有scatter
            }else {
                downIsScatter = cards[i+col] == scatterId;
            }

            if(crrRow == 0) {
                if(downIsScatter) {
                    result[i] = scatterIdDown;
                }else {
                    result[i] = scatterIdUp;
                }
            }else if(crrRow == 4) {
                if(upperIsScatter) {
                    result[i] = scatterIdUp;
                }else {
                    result[i] = scatterIdDown;
                }
            }else {
                if(upperIsScatter) {
                    result[i] = scatterIdUp;
                }else if(downIsScatter) {
                    result[i] = scatterIdDown;
                }
            }
        }
        result = this.processWild(result);
        return result;
    },

    processWild(cards) {
        let result = cards.concat();
        let cfg = this.getGameCfg();
        // if(this.hasWild()) {
        //     result[2] = 1;
        //     result[7] = 101;
        //     result[12] = 102;
        //     result[17] = 103;
        //     result[22] = 104;
        // }
        if (cfg.isWild(result[2]) && cfg.isWild(result[22])) {
            // 整列wild且不需要移动
                result[2] = 1;
                result[7] = 101;
                result[12] = 102;
                result[17] = 103;
                result[22] = 104;
        } else if (cfg.isWild(result[2]) && !cfg.isWild(result[22])) {
            // 下面不是wild,那么要从下开始往上填wild图标
            let firstRow = 3;
            for (let i = 3; i >= 0; i--) {
                if (cfg.isWild(result[i * 5 + 2])) {
                    firstRow = i;
                    break;
                }
            }
            for (let i = 0; i <= firstRow ; i++) {
                result[i * 5 + 2] = 104 - (firstRow - i);
            }
        } else if (!cfg.isWild(result[2]) && cfg.isWild(result[22])) {
            // 上面不是wild，那么要从上往下开始填
            let firstRow = 4;
            for (let i = 0; i < 5; i++) {
                if (cfg.isWild(result[i * 5 + 2])) {
                    firstRow = i;
                    result[i * 5 + 2] = 1;
                    break;
                }
            }
            for (let i = firstRow + 1; i < 5 ; i++) {
                result[i * 5 + 2] = 101 - (firstRow + 1 - i);
            }
        }
        return result;
    },

    hasWild() {
        let cfg = this.getGameCfg();
        let spinData = this.getSpinData().resultCards;
        if(
            cfg.isWild(spinData[2]) ||
            cfg.isWild(spinData[7]) ||
            cfg.isWild(spinData[12]) ||
            cfg.isWild(spinData[17]) ||
            cfg.isWild(spinData[22])
        ) {
            return true;
        }
        return false;
    },

    /**
     * 判断列是否有scatter
     * @param {number}} colId 0~4
     */
    hasScatterByCol(colId) {
        if(colId<1 || colId>3) {
            return false;
        }
        let row = 5;
        let col = 5;
        for(let i=0; i<row; i++) {
            if(GameCfg.isScatter(this.afterProcessingCards[colId + col*i])) {
                return true;
            }
        }
        return false;
    },

    /**
     * 是否可以收集
     * @returns {boolean}
     */
    canCollect() {
        return this.GetBetIdx() >= this._deskInfo.needBet;
    },

    /**
     * 获取结果中收集图标得的下标
     */
    getCollectSymbolIndexs() {
        if(!this.afterProcessingCards || this.afterProcessingCards.length < 1) {
            return [];
        }
        let ret = [];
        this.afterProcessingCards.forEach((v, i)=>{
            if(v == 4) {
                ret.push(i+1);
            }
        });
        return ret;
    },

    /**
     * 请求子游戏数据51
     * @param param
     */
    reqSubGame(param) {
        return new Promise(res=>{
            let req = {
                c:MsgId.SLOT_SUBGAME_DATA,
                gameid:this._gameId,
                data:param
            };
            let resp = (msg)=>{
                cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, resp, false, this);
                res(msg);
            };
            cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, resp, this);
            cc.vv.NetManager.send(req, true);
        });
    },
    ///////////////////////免费相关//////////////////////////////
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.triggerFreeCnt() > 0;
    },

    /**
     * 获取触发免费次数
     */
    triggerFreeCnt() {
        let freeResult = this.getSpinData().freeResult;
        if(freeResult && freeResult.triFreeCnt  && freeResult.freeInfo && freeResult.freeInfo.freeCnt) {
           return freeResult.freeInfo.freeCnt;
        }
        return 0;
    },
    
    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 触发免费游西 获取scatter 下标
     */
    getScatterIndexs() {
        if(this.triggerFreeCnt() > 0) {
            return this.getSpinData().freeResult.freeInfo.scatterIdx.concat();
        }
        return [];
    },

    /**
     * 免费游戏赢取的金币
     */
    getFreeWinCoin() {
        return this._gameInfo.freeWinCoin;
    },
    /////////////////////////随机wild相关//////////////////////////////
    /**
     * 通过倍数获取下标
     * @param {number} multiple 
     */
    getMultipleIndex(multiple) {
        let index = this.wildMultipleList.indexOf(multiple);
        if(index >=0) {
            return index;
        }else {
            console.log(">>>> 获取倍数出错");
            return 0;
        }
    },
    ///////////////////////////收集相关/////////////////
    /**
     * 获取当前收集进度
     */
    getCollectPercent() {
        if(!this.energyData || !this.energyData.progressData) {
            return 0;
        }
        let percent = this.energyData.progressData.totalCnt / this.energyData.progressData.needCnt;
        percent = Math.min(1, percent);
        percent = Math.max(0, percent);
        return percent;
    },

    ///////////////////////////jpgame相关////////////////////////////////////////////////
    /**
    *  获取jackport的值
    */
    getJpValue(jpType) {
        let baseArr = cc.vv.AppData.getGameJackpot(this._gameId);
        //val: 0:mini 1:minor 2:major 3:grand(mega) 4:self define
        let jpBase = 10;
        if (baseArr) {
            jpBase = baseArr[jpType]
        }
        return this.GetTotalBet() * jpBase;
    },

    /**
     * 获取bigwin类型
     * @param {*} winCoin 
     */
    getBigWinType(winCoin) {
        let mul = winCoin/this.singleBet;
        let type = -1;
        if(mul >= 100) {
            type = 5;
        }else if(mul >= 80) {
            type = 4;
        }else if(mul >= 60) {
            type = 3;
        }else if(mul >= 40) {
            type = 2;
        }else if(mul >= 20) {
            type = 1;
        }else if(mul >= 10) {
            type = 0;
        }
        return type;
    },

    /**
     * 触发jp游戏 获取bonus 下标
     */
    getBonusIndexs() {
        let ret = [];
        if(this.afterProcessingCards) {
            for(let i=0; i<this.afterProcessingCards.length; i++) {
                let c = this.afterProcessingCards[i];
                if(c == this.getGameCfg().bonusId) {
                    ret.push(i+1);
                }
            }
        }
        return ret;
    },
});
