/**
 * 判断id 是否为scatter
 * @param {number} id 
 */
Cfg.isScatter = function(id) {
    return id == 2 || id == 201;
};

/**
 * 判断id 是否为wild
 * @param {number} id 
 */
Cfg.isWild = function(id) {
    return id == 1 || id == 101 ||  id == 102 || id == 102 ||  id == 103 ||  id == 104;
};

